/* EventSphere · local-first event operations demo */
(()=>{'use strict';
const KEY='eventsphere.v1', $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const today=new Date(); const day=(n)=>{const d=new Date(today);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const uid=(p='ES')=>`${p}-${Math.random().toString(36).slice(2,6).toUpperCase()}${Date.now().toString().slice(-4)}`;
const dateFmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={events:[
 {id:'EV-2401',name:'Future Forward Summit',category:'Conferences',description:'A gathering of bold thinkers exploring what comes next in business and technology.',date:day(12),start:'09:00',end:'17:30',venueId:'VN-01',fee:249,capacity:420,status:'Published',image:'◈'},
 {id:'EV-2402',name:'Designing for Impact',category:'Workshops',description:'A hands-on creative workshop for people building a more thoughtful digital world.',date:day(18),start:'10:00',end:'16:00',venueId:'VN-02',fee:89,capacity:120,status:'Published',image:'✳'},
 {id:'EV-2403',name:'The Makers Market',category:'Exhibitions',description:'Independent makers, makerspaces and modern craft under one roof.',date:day(24),start:'11:00',end:'19:00',venueId:'VN-03',fee:25,capacity:850,status:'Draft',image:'✧'},
 {id:'EV-2404',name:'Culture in Bloom',category:'Festivals',description:'An open-air celebration of local music, art and good food.',date:day(31),start:'12:00',end:'21:00',venueId:'VN-04',fee:45,capacity:1200,status:'Published',image:'❋'}],
 venues:[{id:'VN-01',name:'The Foundry — Main Hall',location:'Brooklyn, NY',capacity:500,facilities:'Stage, AV, Wi-Fi',availability:'Available',contact:'hello@foundry.co'},{id:'VN-02',name:'Studio 37',location:'Manhattan, NY',capacity:150,facilities:'Projector, breakout rooms',availability:'Available',contact:'events@studio37.co'},{id:'VN-03',name:'Pier 9 Exhibition Space',location:'Brooklyn, NY',capacity:1000,facilities:'Loading bay, Wi-Fi',availability:'Available',contact:'bookings@pier9.co'},{id:'VN-04',name:'Botanical Gardens',location:'Queens, NY',capacity:1500,facilities:'Outdoor stage, catering',availability:'Available',contact:'events@gardens.co'}],
 participants:[{id:'PT-001',name:'Olivia Chen',email:'olivia.chen@example.com',phone:'+1 212 555 0141'},{id:'PT-002',name:'Marcus Williams',email:'marcus.w@example.com',phone:'+1 917 555 0182'},{id:'PT-003',name:'Priya Sharma',email:'priya.s@example.com',phone:'+1 646 555 0113'},{id:'PT-004',name:'Theo Martin',email:'theo.m@example.com',phone:'+1 718 555 0164'}],
 registrations:[{id:'REG-8401',participantId:'PT-001',eventId:'EV-2401',date:day(-2),payment:'Paid',status:'Approved',attendance:'Not marked'},{id:'REG-8402',participantId:'PT-002',eventId:'EV-2401',date:day(-1),payment:'Paid',status:'Approved',attendance:'Not marked'},{id:'REG-8403',participantId:'PT-003',eventId:'EV-2402',date:day(-1),payment:'Pending',status:'Pending',attendance:'Not marked'},{id:'REG-8404',participantId:'PT-004',eventId:'EV-2402',date:day(0),payment:'Paid',status:'Approved',attendance:'Not marked'}],
 speakers:[{id:'SP-01',name:'Jordan Lee',email:'jordan@northstar.io',phone:'+1 415 555 0110',organization:'Northstar Labs',role:'Founder & CEO',expertise:'Future of work',eventId:'EV-2401',session:'The human side of innovation'},{id:'SP-02',name:'Amara Okafor',email:'amara@studio.co',phone:'+1 212 555 0192',organization:'Studio Amara',role:'Creative Director',expertise:'Inclusive design',eventId:'EV-2402',session:'Designing for everyone'}],
 sessions:[{id:'SS-01',eventId:'EV-2401',title:'Opening keynote: A better tomorrow',speakerId:'SP-01',date:day(12),start:'09:30',end:'10:15',venueId:'VN-01'},{id:'SS-02',eventId:'EV-2401',title:'Building teams for change',speakerId:'',date:day(12),start:'11:00',end:'12:00',venueId:'VN-01'},{id:'SS-03',eventId:'EV-2402',title:'Designing for everyone',speakerId:'SP-02',date:day(18),start:'10:30',end:'11:30',venueId:'VN-02'}],
 payments:[{id:'PAY-8401',registrationId:'REG-8401',amount:249,status:'Completed',date:day(-2),method:'Card ···· 4242'},{id:'PAY-8402',registrationId:'REG-8402',amount:249,status:'Completed',date:day(-1),method:'Card ···· 1808'},{id:'PAY-8403',registrationId:'REG-8403',amount:89,status:'Pending',date:day(-1),method:'—'},{id:'PAY-8404',registrationId:'REG-8404',amount:89,status:'Completed',date:day(0),method:'Card ···· 3011'}],
 feedback:[{id:'FB-01',eventId:'EV-2401',participantId:'PT-001',rating:5,speakerRating:5,venueRating:4,experience:'Thoughtful programming and an incredibly welcoming room.',suggestions:'More time for the closing conversations.',date:day(-1)}],
 organizers:[{id:'OR-01',name:'Alex Morgan',email:'alex@northstar.studio',role:'Event director',eventId:'EV-2401',responsibility:'Overall planning'},{id:'OR-02',name:'Sam Rivera',email:'sam@northstar.studio',role:'Operations lead',eventId:'EV-2402',responsibility:'Venue & logistics'}],
 notifications:[{id:'NT-01',title:'New registration received',body:'Olivia Chen registered for Future Forward Summit.',date:day(0),read:false},{id:'NT-02',title:'Event coming up soon',body:'Future Forward Summit is 12 days away.',date:day(0),read:false},{id:'NT-03',title:'Payment confirmed',body:'A payment of $249.00 was processed successfully.',date:day(-1),read:true}]};
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed}catch{db=seed}Object.keys(seed).forEach(k=>{if(!Array.isArray(db[k]))db[k]=seed[k]});
const save=()=>localStorage.setItem(KEY,JSON.stringify(db)), by=(key,id)=>db[key].find(x=>x.id===id), eventName=id=>by('events',id)?.name||'Deleted event', venueName=id=>by('venues',id)?.name||'—', personName=id=>by('participants',id)?.name||'—', speakerName=id=>by('speakers',id)?.name||'Unassigned';
if(!localStorage.getItem(KEY))save(); let active='dashboard', charts=[];
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toastStack').append(el);setTimeout(()=>el.remove(),3200)}
function removeChart(){charts.forEach(c=>c.destroy());charts=[]}
function navTo(page){active=page;$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=({dashboard:'Overview',schedule:'Schedule & sessions',reports:'Reports & analytics'})[page]||page[0].toUpperCase()+page.slice(1);render();$('#sidebar').classList.remove('open');window.scrollTo(0,0)}
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navTo(b.dataset.page)});$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#topNotifications').onclick=()=>navTo('notifications');$('#globalSearch').onclick=()=>{navTo('events');setTimeout(()=>$('.field-search')?.focus(),60)};
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">MONDAY, ${new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}).toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(text,action,primary=false,extra=''){return `<button class="btn ${primary?'btn-primary':''} ${extra}" data-action="${action}">${text}</button>`}
function stats(items){return `<div class="stats-grid">${items.map(([label,value,icon,tone,foot])=>`<article class="stat-card"><div class="stat-top">${label}<span class="stat-icon icon-${tone}">${icon}</span></div><div class="stat-number">${value}</div><div class="stat-foot">${foot||'<span class="trend-up">↗ 12%</span> vs. last month'}</div></article>`).join('')}</div>`}
function pill(text){let c=['Paid','Completed','Present','Published','Approved','Available','Read'].includes(text)?'green':['Pending','Draft','Not marked','Scheduled'].includes(text)?'orange':['Cancelled','Failed','Absent','Unavailable'].includes(text)?'gray':'';return `<span class="pill ${c}">${esc(text||'—')}</span>`}
function eventRows(rows){return rows.map(e=>`<tr><td><div class="event-cell"><span class="event-thumb">${e.image||'◈'}</span><span>${esc(e.name)}<small style="display:block;color:#999;font-size:9px;font-weight:400;margin-top:3px">${esc(e.category)}</small></span></div></td><td>${dateFmt(e.date)}</td><td>${esc(venueName(e.venueId))}</td><td>${db.registrations.filter(r=>r.eventId===e.id).length} / ${e.capacity}</td><td>${pill(e.status)}</td><td><div class="row-actions"><button class="action-btn" data-action="edit-event" data-id="${e.id}">Edit</button><button class="action-btn" data-action="view-event" data-id="${e.id}">View</button></div></td></tr>`).join('')}
function dashboard(){let soon=db.events.filter(e=>e.date>=day(0)), done=db.events.filter(e=>e.date<day(0));let rev=db.payments.filter(p=>p.status==='Completed').reduce((s,p)=>s+Number(p.amount),0);return `${heading('Good morning, Alex 👋','Welcome to EventSphere — plan, manage & experience events smarter.',button('＋ &nbsp; Create event','new-event',true))}${stats([['Total events',db.events.length,'◈','purple','<span class="trend-up">↗ 12%</span> vs. last month'],['Upcoming events',soon.length,'◷','green','Across your next 30 days'],['Completed events',done.length,'✓','orange','Events held to date'],['Total participants',db.participants.length,'♙','blue','Registered in your workspace'],['Total registrations',db.registrations.length,'▤','purple','Across all events'],['Total revenue',money(rev),'＄','green','From completed payments'],['Total venues',db.venues.length,'⌂','orange','Available event spaces'],['Total speakers',db.speakers.length,'♧','blue','On your speaker roster']])}<div class="dash-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Registration overview</div><div class="panel-sub">A look at your attendee growth</div></div><select class="filter-select" id="chartRange"><option>Last 7 months</option><option>Last 30 days</option></select></div><div class="chart-box"><canvas id="registrationChart"></canvas></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Events by category</div><div class="panel-sub">Your event mix at a glance</div></div><button class="text-link" data-action="go-events">View all</button></div><div class="donut-wrap"><div class="donut-chart"><canvas id="categoryChart"></canvas></div><div class="legend-list">${['Conferences','Workshops','Exhibitions','Festivals'].map((c,i)=>`<div class="legend-item"><span class="legend-dot" style="background:${['#7a65e8','#52bd94','#f3ab63','#7da5e5'][i]}"></span>${c}<strong>${db.events.filter(e=>e.category===c).length}</strong></div>`).join('')}</div></div></section></div><div class="dash-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Your events</div><div class="panel-sub">Keep an eye on what's happening</div></div><button class="text-link" data-action="go-events">All events →</button></div><table class="events-table"><thead><tr><th>EVENT</th><th>DATE</th><th>VENUE</th><th>ATTENDEES</th><th>STATUS</th><th></th></tr></thead><tbody>${eventRows([...db.events].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3))}</tbody></table></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Coming up next</div><div class="panel-sub">Your upcoming schedule</div></div><button class="text-link" data-action="go-schedule">Full schedule →</button></div><div class="schedule-list">${db.sessions.slice(0,3).map(s=>`<div class="schedule-item"><div class="schedule-time"><strong>${s.start}</strong>${new Date(s.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</div><div class="schedule-desc"><strong>${esc(s.title)}</strong><small>${esc(eventName(s.eventId))} · ${esc(speakerName(s.speakerId))}</small></div></div>`).join('')||'<div class="empty">No sessions scheduled yet.</div>'}</div></section></div>`}
const cats=['Conferences','Workshops','Exhibitions','Festivals','Corporate Events','Technical Events','Cultural Events'];
function eventsPage(){return `${heading('Events','Bring every moving piece of your events together.',button('＋ &nbsp; Create event','new-event',true))}<div class="toolbar" style="padding:0 0 14px;border:0"><input class="field-search" id="eventSearch" placeholder="⌕  Search events..."><select class="filter-select" id="eventCat"><option value="">All categories</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select><select class="filter-select" id="eventStatus"><option value="">All statuses</option>${['Published','Draft','Completed','Cancelled'].map(c=>`<option>${c}</option>`).join('')}</select><div class="spacer"></div>${button('⇅ &nbsp; Sort by date','sort-events')}</div><div class="cards-grid" id="eventCards">${eventCards(db.events)}</div>`}
function eventCards(rows){return rows.length?rows.map(e=>`<article class="event-card"><div class="event-cover ${({'Workshops':'cover-orange','Exhibitions':'cover-blue','Festivals':'cover-green','Corporate Events':'cover-rose'}[e.category]||'')}"><span class="pill">${esc(e.category)}</span><span class="cover-icon">${e.image||'◈'}</span></div><div class="event-card-body"><div style="font-size:9px;color:#888">◷ &nbsp;${dateFmt(e.date)} · ${esc(e.start)}</div><h3>${esc(e.name)}</h3><p>${esc(e.description||'An upcoming EventSphere gathering.')}</p><div class="event-meta"><span>⌂ &nbsp;${esc(venueName(e.venueId))}</span><span>${db.registrations.filter(r=>r.eventId===e.id).length}/${e.capacity} seats</span></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:11px">${pill(e.status)}<span class="row-actions"><button class="action-btn" data-action="view-event" data-id="${e.id}">Details</button><button class="action-btn" data-action="edit-event" data-id="${e.id}">Edit</button><button class="action-btn" data-action="delete-event" data-id="${e.id}">Delete</button></span></div></div></article>`).join(''):'<div class="panel empty" style="grid-column:1/-1">No events match your search. Create one to get started.</div>'}
const configs={venues:{title:'Venues',sub:'Find the right place for every memorable moment.',add:'Add venue',kind:'venue',fields:[['name','Venue name','text',true],['location','Location','text',true],['capacity','Capacity','number',true],['facilities','Facilities','text'],['availability','Availability','select',['Available','Unavailable']],['contact','Contact email','email']]},participants:{title:'Participants',sub:'Get to know the people who make your events matter.',add:'Add participant',kind:'participant',fields:[['name','Full name','text',true],['email','Email address','email',true],['phone','Phone number','tel',true]]},registrations:{title:'Registrations',sub:'Track every attendee and their path to your events.',add:'Register attendee',kind:'registration'},payments:{title:'Payments',sub:'A clear picture of your event revenue and payment status.',add:'Record payment',kind:'payment'},speakers:{title:'Speakers',sub:'The voices, ideas and expertise behind your events.',add:'Add speaker',kind:'speaker',fields:[['name','Speaker name','text',true],['email','Email address','email',true],['phone','Phone','tel'],['organization','Organization','text'],['role','Professional role','text'],['expertise','Expertise','text'],['eventId','Assigned event','event',true],['session','Session details','text']]},organizers:{title:'Organizers',sub:'Your team, in sync from first idea to final applause.',add:'Add organizer',kind:'organizer',fields:[['name','Full name','text',true],['email','Email address','email',true],['role','Role','text'],['eventId','Assigned event','event'],['responsibility','Responsibility','text']]}};
function genericPage(key){let c=configs[key],rows=db[key];let counts=key==='payments'?[['Total revenue',money(db.payments.filter(x=>x.status==='Completed').reduce((a,b)=>a+Number(b.amount),0)),'＄','green','Completed transactions'],['Pending',db.payments.filter(x=>x.status==='Pending').length,'◷','orange','Awaiting payment'],['Completed',db.payments.filter(x=>x.status==='Completed').length,'✓','purple','Successfully processed'],['Failed',db.payments.filter(x=>x.status==='Failed').length,'×','blue','Payment attempts']]:key==='registrations'?[['Total registrations',rows.length,'▤','purple','All event registrations'],['Approved',rows.filter(x=>x.status==='Approved').length,'✓','green','Ready to attend'],['Pending',rows.filter(x=>x.status==='Pending').length,'◷','orange','Awaiting approval'],['Paid',rows.filter(x=>x.payment==='Paid').length,'＄','blue','Payment complete']]:null;return `${heading(c.title,c.sub,button('＋ &nbsp; '+c.add,'new-'+c.kind,true))}${counts?stats(counts):''}<div class="table-wrap"><div class="toolbar"><input class="field-search" id="tableSearch" placeholder="⌕  Search ${c.title.toLowerCase()}...">${key==='registrations'?`<select class="filter-select" id="registrationEventFilter"><option value="">All events</option>${db.events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select>`:''}<select class="filter-select" id="tableFilter"><option value="">${key==='payments'||key==='registrations'?'All statuses':`All ${c.title.toLowerCase()}`}</option>${(key==='payments'?['Completed','Pending','Failed']:key==='registrations'?['Paid','Pending','Failed','Approved','Cancelled']:key==='venues'?['Available','Unavailable']:[]).map(s=>`<option>${s}</option>`).join('')}</select><div class="spacer"></div>${key==='payments'?button('↓ &nbsp; Export CSV','export-payments'):''}</div><div id="tableContainer">${tableFor(key,rows)}</div></div>`}
function tableFor(key,rows){if(!rows?.length)return '<div class="empty">Nothing here yet. Add a record to get started.</div>';let heads,body;switch(key){case'venues':heads=['VENUE','LOCATION','CAPACITY','FACILITIES','AVAILABILITY','ACTIONS'];body=rows.map(x=>[`<strong>${esc(x.name)}</strong>`,`<span>${esc(x.location)}</span>`,x.capacity,esc(x.facilities||'—'),pill(x.availability),actions('venue',x.id)]);break;case'participants':heads=['PARTICIPANT','EMAIL','PHONE','REGISTRATIONS','ATTENDANCE','ACTIONS'];body=rows.map(x=>[`<strong>${esc(x.name)}</strong>`,esc(x.email),esc(x.phone),db.registrations.filter(r=>r.participantId===x.id).length,db.registrations.filter(r=>r.participantId===x.id&&r.attendance==='Present').length+' present',actions('participant',x.id)]);break;case'registrations':heads=['REGISTRATION ID','PARTICIPANT','EVENT','REGISTERED','PAYMENT','STATUS','ACTIONS'];body=rows.map(x=>[`<strong>${x.id}</strong>`,esc(personName(x.participantId)),esc(eventName(x.eventId)),dateFmt(x.date),pill(x.payment),pill(x.status),`<div class="row-actions">${x.status==='Pending'?`<button class="action-btn" data-action="approve-reg" data-id="${x.id}">Approve</button>`:''}<button class="action-btn" data-action="cancel-reg" data-id="${x.id}">Cancel</button></div>`]);break;case'payments':heads=['TRANSACTION','REGISTRATION','PARTICIPANT','EVENT','DATE','AMOUNT','STATUS',''];body=rows.map(x=>{let r=by('registrations',x.registrationId);return [`<strong>${x.id}</strong>`,esc(x.registrationId),esc(personName(r?.participantId)),esc(eventName(r?.eventId)),dateFmt(x.date),money(x.amount),pill(x.status),`<button class="action-btn" data-action="invoice" data-id="${x.id}">Invoice</button>`]});break;case'speakers':heads=['SPEAKER','ORGANIZATION','ROLE & EXPERTISE','ASSIGNED EVENT','SESSION','ACTIONS'];body=rows.map(x=>[`<strong>${esc(x.name)}</strong><small style="display:block;color:#999">${esc(x.email)}</small>`,esc(x.organization||'—'),`${esc(x.role||'—')}<small style="display:block;color:#999">${esc(x.expertise||'')}</small>`,esc(eventName(x.eventId)),esc(x.session||'—'),actions('speaker',x.id)]);break;case'organizers':heads=['ORGANIZER','EMAIL','ROLE','ASSIGNED EVENT','RESPONSIBILITY','ACTIONS'];body=rows.map(x=>[`<strong>${esc(x.name)}</strong>`,esc(x.email),esc(x.role),esc(eventName(x.eventId)),esc(x.responsibility),actions('organizer',x.id)]);break;default: return '<div class="empty">No data available.</div>'}return `<table class="data-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function actions(kind,id){return `<div class="row-actions"><button class="action-btn" data-action="edit-${kind}" data-id="${id}">Edit</button><button class="action-btn" data-action="delete-${kind}" data-id="${id}">Delete</button></div>`}
function schedulePage(){return `${heading('Schedule & sessions','Every session, speaker and space, all in one place.',button('＋ &nbsp; Add session','new-session',true))}<div class="panel"><div class="panel-head"><div><div class="panel-title">Upcoming sessions</div><div class="panel-sub">Sessions across all scheduled events</div></div><span class="pill">${db.sessions.length} sessions</span></div>${db.sessions.length?`<table class="data-table"><thead><tr><th>DATE & TIME</th><th>SESSION</th><th>EVENT</th><th>SPEAKER</th><th>VENUE</th><th>ACTIONS</th></tr></thead><tbody>${[...db.sessions].sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).map(s=>`<tr><td><strong>${dateFmt(s.date)}</strong><small style="display:block;color:#999;margin-top:3px">${s.start} – ${s.end}</small></td><td><strong>${esc(s.title)}</strong></td><td>${esc(eventName(s.eventId))}</td><td>${esc(speakerName(s.speakerId))}</td><td>${esc(venueName(s.venueId))}</td><td>${actions('session',s.id)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No sessions scheduled. Add your first session.</div>'}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Schedule notes</div><div class="panel-sub">A quick view of your event calendar</div></div></div><div class="schedule-list">${db.events.filter(e=>e.date>=day(0)).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="schedule-item"><div class="schedule-time"><strong>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</strong>${e.start}</div><div class="schedule-desc"><strong>${esc(e.name)}</strong><small>${esc(venueName(e.venueId))} · ${db.sessions.filter(s=>s.eventId===e.id).length} sessions planned</small></div></div>`).join('')||'<div class="empty">No upcoming events.</div>'}</div></div>`}
function attendancePage(){let regs=db.registrations, present=regs.filter(r=>r.attendance==='Present').length;return `${heading('Attendance','A live picture of who showed up and who didn’t.',button('↓ &nbsp; Export report','export-attendance'))}${stats([['Registered',regs.length,'♙','purple','Across all events'],['Present',present,'✓','green','Marked as attended'],['Absent',regs.filter(r=>r.attendance==='Absent').length,'×','orange','Marked absent'],['Attendance rate',regs.length?Math.round(present/regs.length*100)+'%':'0%','◉','blue','Of all registrants']])}<div class="table-wrap"><div class="toolbar"><input class="field-search" id="tableSearch" placeholder="⌕  Search attendees..."><select class="filter-select" id="eventFilter"><option value="">All events</option>${db.events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div id="tableContainer">${attendanceTable(regs)}</div></div>`}
function attendanceTable(rows){if(!rows.length)return '<div class="empty">No registrations to track yet.</div>';return `<table class="data-table"><thead><tr><th>PARTICIPANT</th><th>EVENT</th><th>REGISTRATION</th><th>ATTENDANCE</th><th>UPDATE</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(personName(r.participantId))}</strong></td><td>${esc(eventName(r.eventId))}</td><td>${dateFmt(r.date)}</td><td>${pill(r.attendance)}</td><td><button class="action-btn" data-action="attendance" data-id="${r.id}" data-value="Present">✓ Present</button> <button class="action-btn" data-action="attendance" data-id="${r.id}" data-value="Absent">× Absent</button></td></tr>`).join('')}</tbody></table>`}
function feedbackPage(){let rows=db.feedback,avg=rows.length?rows.reduce((a,b)=>a+Number(b.rating),0)/rows.length:0;return `${heading('Feedback','Listen closely. Make every next event even better.',button('＋ &nbsp; Add feedback','new-feedback',true))}${stats([['Responses',rows.length,'▤','purple','All submitted feedback'],['Average rating',avg?avg.toFixed(1)+' / 5':'—','☆','orange','Across all events'],['Speaker rating',rows.length?(rows.reduce((a,b)=>a+Number(b.speakerRating||0),0)/rows.length).toFixed(1)+' / 5':'—','♧','green','Average speaker score'],['Venue rating',rows.length?(rows.reduce((a,b)=>a+Number(b.venueRating||0),0)/rows.length).toFixed(1)+' / 5':'—','⌂','blue','Average venue score']])}<div class="cards-grid">${rows.length?rows.map(f=>`<article class="mini-card"><div style="display:flex;justify-content:space-between;align-items:center"><strong>${esc(personName(f.participantId))}</strong><span class="feedback-stars">${'★'.repeat(f.rating)}${'☆'.repeat(5-f.rating)}</span></div><div class="panel-sub" style="margin:7px 0 10px">${esc(eventName(f.eventId))} · ${dateFmt(f.date)}</div><p>${esc(f.experience)}</p><p style="margin-top:7px"><b>Suggestion:</b> ${esc(f.suggestions||'—')}</p><button class="action-btn" style="margin-top:10px" data-action="delete-feedback" data-id="${f.id}">Delete</button></article>`).join(''):'<div class="panel empty" style="grid-column:1/-1">No feedback yet. Add a response to begin tracking event experience.</div>'}</div>`}
function certificatesPage(){return `${heading('Certificates','Celebrate the people who showed up.',button('＋ &nbsp; Create certificate','certificate-form',true))}<div class="panel"><div class="panel-head"><div><div class="panel-title">Generate a participation certificate</div><div class="panel-sub">Choose an attendee and event to make a downloadable certificate.</div></div></div><div class="form-grid"><div class="form-field"><label>Event</label><select class="input" id="certEvent">${db.events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div class="form-field"><label>Participant</label><select class="input" id="certPerson">${db.participants.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div></div><div style="margin-top:15px">${button('Generate certificate','generate-cert',true)}</div></div><div id="certificateArea"></div>`}
function reportsPage(){return `${heading('Reports & analytics','Turn event activity into clear next steps.',button('↓ &nbsp; Export registrations','export-registrations'))}<div class="report-summary"><div class="mini-card"><div class="stat-top">Registration conversion</div><strong>${db.events.length?Math.min(100,Math.round(db.registrations.length/Math.max(1,db.events.reduce((s,e)=>s+Number(e.capacity),0))*100))+'%':'—'}</strong><div class="panel-sub">Registered seats / capacity</div></div><div class="mini-card"><div class="stat-top">Gross revenue</div><strong>${money(db.payments.filter(p=>p.status==='Completed').reduce((s,p)=>s+Number(p.amount),0))}</strong><div class="panel-sub">Completed simulated payments</div></div><div class="mini-card"><div class="stat-top">Average event rating</div><strong>${db.feedback.length?(db.feedback.reduce((s,f)=>s+Number(f.rating),0)/db.feedback.length).toFixed(1)+' ★':'—'}</strong><div class="panel-sub">From submitted feedback</div></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Registrations by event</div><div class="panel-sub">Participant count for each event</div></div></div><div class="chart-box bar-chart"><canvas id="reportEvents"></canvas></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Revenue by event</div><div class="panel-sub">Completed payments</div></div></div><div class="chart-box bar-chart"><canvas id="reportRevenue"></canvas></div></section></div><section class="panel"><div class="panel-head"><div><div class="panel-title">Event-wise report</div><div class="panel-sub">Registrations, attendance and revenue</div></div><button class="text-link" data-action="export-registrations">Export CSV ↓</button></div><table class="data-table"><thead><tr><th>EVENT</th><th>CATEGORY</th><th>REGISTRATIONS</th><th>PRESENT</th><th>REVENUE</th><th>RATING</th></tr></thead><tbody>${db.events.map(e=>{let rs=db.registrations.filter(r=>r.eventId===e.id),ps=db.payments.filter(p=>p.status==='Completed'&&rs.some(r=>r.id===p.registrationId));let fs=db.feedback.filter(f=>f.eventId===e.id);return `<tr><td><strong>${esc(e.name)}</strong></td><td>${esc(e.category)}</td><td>${rs.length}</td><td>${rs.filter(r=>r.attendance==='Present').length}</td><td>${money(ps.reduce((s,p)=>s+Number(p.amount),0))}</td><td>${fs.length?(fs.reduce((s,f)=>s+Number(f.rating),0)/fs.length).toFixed(1)+' ★':'—'}</td></tr>`}).join('')}</tbody></table></section>`}
function notificationsPage(){return `${heading('Notifications','A little heads-up, right when you need it.',button('Mark all as read','read-notifications'))}<div class="panel">${db.notifications.length?db.notifications.map(n=>`<div class="notice-card"><div class="notice-icon">${n.title.toLowerCase().includes('payment')?'＄':n.title.toLowerCase().includes('event')?'◷':'♙'}</div><div style="flex:1"><strong>${esc(n.title)}</strong>${n.read?'':' <span class="pill">New</span>'}<p>${esc(n.body)}</p><small>${dateFmt(n.date)}</small></div><button class="action-btn" data-action="delete-notification" data-id="${n.id}">Dismiss</button></div>`).join(''):'<div class="empty">You are all caught up.</div>'}</div>`}
function settingsPage(){return `${heading('Settings','Manage your workspace preferences and demo data.','')}<div class="panel" style="max-width:680px"><div class="panel-head"><div><div class="panel-title">Workspace preferences</div><div class="panel-sub">These settings are stored in this browser.</div></div></div><div class="form-grid"><div class="form-field"><label>Workspace name</label><input value="Northstar Studio" id="settingWorkspace"></div><div class="form-field"><label>Currency</label><select id="settingCurrency"><option>USD — US Dollar</option><option>INR — Indian Rupee</option><option>EUR — Euro</option></select></div><div class="form-field"><label>Event notifications</label><select><option>All activity</option><option>Important only</option><option>Off</option></select></div><div class="form-field"><label>Default event timezone</label><select><option>America/New_York (ET)</option><option>Asia/Kolkata (IST)</option><option>UTC</option></select></div></div><div class="modal-actions">${button('Save preferences','save-settings',true)}</div><hr style="border:0;border-top:1px solid #eee;margin:21px 0"><div class="panel-title">Demo data</div><p class="panel-sub" style="line-height:1.6">Your EventSphere records are saved in this browser. Resetting restores the original sample workspace.</p>${button('Reset to sample data','reset-data',false,'')}</div><div class="panel" style="max-width:680px;margin-top:15px"><div class="panel-title">About this demo</div><p class="panel-sub" style="line-height:1.7">EventSphere is a frontend simulation. Payments are simulated only; no real payment gateway or external event service is connected. Your data stays in this browser using LocalStorage.</p></div>`}
function render(){removeChart();$('#eventCount').textContent=db.events.length;let html=active==='dashboard'?dashboard():active==='events'?eventsPage():configs[active]?genericPage(active):active==='schedule'?schedulePage():active==='attendance'?attendancePage():active==='feedback'?feedbackPage():active==='certificates'?certificatesPage():active==='reports'?reportsPage():active==='notifications'?notificationsPage():settingsPage();$('#pageRoot').innerHTML=html;attachFilters();if(active==='dashboard'||active==='reports')setTimeout(drawCharts,20)}
function drawCharts(){if(typeof Chart==='undefined')return;Chart.defaults.font.family='DM Sans';Chart.defaults.font.size=10;Chart.defaults.color='#9292a4';if($('#registrationChart'))charts.push(new Chart($('#registrationChart'),{type:'line',data:{labels:['May','Jun','Jul','Aug','Sep','Oct','Nov'],datasets:[{label:'Registrations',data:[18,26,22,41,35,57,68],borderColor:'#7964e8',backgroundColor:'#7964e81a',fill:true,tension:.4,pointRadius:3,pointBackgroundColor:'#7964e8'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},border:{display:false}},y:{grid:{color:'#f1f1f5'},border:{display:false},beginAtZero:true,ticks:{precision:0}}}}}));if($('#categoryChart'))charts.push(new Chart($('#categoryChart'),{type:'doughnut',data:{labels:cats.slice(0,4),datasets:[{data:['Conferences','Workshops','Exhibitions','Festivals'].map(c=>db.events.filter(e=>e.category===c).length||0.25),backgroundColor:['#7a65e8','#52bd94','#f3ab63','#7da5e5'],borderWidth:0,hoverOffset:5}]},options:{cutout:'70%',plugins:{legend:{display:false}},maintainAspectRatio:false}}));if($('#reportEvents'))charts.push(new Chart($('#reportEvents'),{type:'bar',data:{labels:db.events.map(e=>e.name.length>18?e.name.slice(0,18)+'…':e.name),datasets:[{data:db.events.map(e=>db.registrations.filter(r=>r.eventId===e.id).length),backgroundColor:'#8875eb',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},border:{display:false}},y:{grid:{color:'#f1f1f5'},border:{display:false},beginAtZero:true,ticks:{precision:0}}}}}));if($('#reportRevenue'))charts.push(new Chart($('#reportRevenue'),{type:'bar',data:{labels:db.events.map(e=>e.name.length>18?e.name.slice(0,18)+'…':e.name),datasets:[{data:db.events.map(e=>db.payments.filter(p=>p.status==='Completed'&&db.registrations.some(r=>r.id===p.registrationId&&r.eventId===e.id)).reduce((s,p)=>s+Number(p.amount),0)),backgroundColor:'#55bd96',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},border:{display:false}},y:{grid:{color:'#f1f1f5'},border:{display:false},beginAtZero:true}}}}))}
render();
function optionsFor(type,value=''){let list=type==='event'?db.events.map(e=>[e.id,e.name]):type==='venue'?db.venues.map(v=>[v.id,v.name]):type==='person'?db.participants.map(p=>[p.id,p.name]):type==='speaker'?db.speakers.map(s=>[s.id,s.name]):[];return `<option value="">Choose…</option>${list.map(([id,n])=>`<option value="${id}" ${id===value?'selected':''}>${esc(n)}</option>`).join('')}`}
function fieldHtml([name,label,type,required],value=''){if(type==='event'||type==='venue'||type==='person'||type==='speaker')return `<div class="form-field"><label>${label}${required?' *':''}</label><select name="${name}" ${required?'required':''}>${optionsFor(type,value)}</select></div>`;if(type==='select')return `<div class="form-field"><label>${label}</label><select name="${name}">${(required||[]).map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}</select></div>`;return `<div class="form-field"><label>${label}${required?' *':''}</label><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='email'?'pattern="[^ @]+@[^ @]+\\.[^ @]+"':''}></div>`}
function openModal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal">×</button></div>${body}`;$('#modalBackdrop').classList.add('open')}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
function eventForm(row={}){openModal(row.id?'Edit event':'Create an event',`<form class="modal-form" id="recordForm" data-kind="event" data-id="${row.id||''}"><div class="form-grid">${[['name','Event name','text',true],['category','Category','select',cats],['description','Description','textarea'],['date','Event date','date',true],['start','Start time','time',true],['end','End time','time',true],['venueId','Venue','venue',true],['fee','Registration fee ($)','number',true],['capacity','Maximum participants','number',true],['status','Event status','select',['Draft','Published','Completed','Cancelled']]].map(f=>f[2]==='select'&&f[0]==='category'?`<div class="form-field"><label>Category *</label><select name="category" required>${cats.map(c=>`<option ${c===(row.category||'Conferences')?'selected':''}>${c}</option>`).join('')}</select></div>`:f[2]==='textarea'?`<div class="form-field full"><label>Description</label><textarea name="description">${esc(row.description||'')}</textarea></div>`:f[0]==='venueId'?fieldHtml(f,row.venueId):f[2]==='select'?fieldHtml(f,row.status||'Draft'):fieldHtml(f,row[f[0]]??(f[0]==='fee'?0:f[0]==='capacity'?100:''))).join('')}</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">${row.id?'Save changes':'Create event'}</button></div></form>`)}
function simpleForm(kind,row={}){let conf=kind==='venue'?configs.venues:kind==='participant'?configs.participants:kind==='speaker'?configs.speakers:kind==='organizer'?configs.organizers:null;let title=row.id?'Edit':'Add';let body='';if(conf){body=`<form class="modal-form" id="recordForm" data-kind="${kind}" data-id="${row.id||''}"><div class="form-grid">${conf.fields.map(f=>fieldHtml(f,row[f[0]])).join('')}</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">${title} ${kind}</button></div></form>`}else if(kind==='registration'){body=`<form class="modal-form" id="registrationForm"><div class="form-grid"><div class="form-field"><label>Event *</label><select name="eventId" required>${optionsFor('event')}</select></div><div class="form-field"><label>Participant *</label><select name="participantId" required>${optionsFor('person')}</select></div><div class="form-field"><label>Registration fee</label><input id="regFee" readonly></div><div class="form-field"><label>Payment status</label><select name="payment"><option>Paid</option><option>Pending</option></select></div></div><div class="panel-sub" style="margin-top:10px">Fees are taken from the selected event. Payment is simulated for this demo.</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">Confirm registration</button></div></form>`}else if(kind==='session'){body=`<form class="modal-form" id="recordForm" data-kind="session" data-id="${row.id||''}"><div class="form-grid"><div class="form-field"><label>Session title *</label><input name="title" required value="${esc(row.title||'')}"></div><div class="form-field"><label>Event *</label><select name="eventId" required>${optionsFor('event',row.eventId)}</select></div><div class="form-field"><label>Speaker</label><select name="speakerId">${optionsFor('speaker',row.speakerId)}</select></div><div class="form-field"><label>Venue or hall *</label><select name="venueId" required>${optionsFor('venue',row.venueId)}</select></div><div class="form-field"><label>Session date *</label><input type="date" name="date" required value="${row.date||''}"></div><div class="form-field"><label>Start time *</label><input type="time" name="start" required value="${row.start||''}"></div><div class="form-field"><label>End time *</label><input type="time" name="end" required value="${row.end||''}"></div></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save session</button></div></form>`}else if(kind==='payment'){body=`<form class="modal-form" id="paymentForm"><div class="form-grid"><div class="form-field full"><label>Registration *</label><select name="registrationId" required>${db.registrations.map(r=>`<option value="${r.id}">${esc(personName(r.participantId))} · ${esc(eventName(r.eventId))} · ${r.id}</option>`).join('')}</select></div><div class="form-field"><label>Amount ($) *</label><input type="number" name="amount" min="0" required></div><div class="form-field"><label>Status</label><select name="status"><option>Completed</option><option>Pending</option><option>Failed</option></select></div></div><div class="panel-sub" style="margin-top:9px">Simulation only. No banking details or real payment processing.</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">Record payment</button></div></form>`}else if(kind==='feedback'){body=`<form class="modal-form" id="recordForm" data-kind="feedback"><div class="form-grid"><div class="form-field"><label>Event *</label><select name="eventId" required>${optionsFor('event')}</select></div><div class="form-field"><label>Participant *</label><select name="participantId" required>${optionsFor('person')}</select></div>${['rating','speakerRating','venueRating'].map((n,i)=>`<div class="form-field"><label>${['Event','Speaker','Venue'][i]} rating *</label><select name="${n}">${[5,4,3,2,1].map(v=>`<option>${v}</option>`).join('')}</select></div>`).join('')}<div class="form-field full"><label>Event experience</label><textarea name="experience" required></textarea></div><div class="form-field full"><label>Suggestions</label><textarea name="suggestions"></textarea></div></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save feedback</button></div></form>`}
openModal(`${title} ${kind}`,body);if(kind==='registration'){let select=$('[name=eventId]'),fee=$('#regFee');const sync=()=>fee.value=money(by('events',select.value)?.fee||0);select.addEventListener('change',sync);sync()}}
function readForm(form){return Object.fromEntries(new FormData(form).entries())}
function validPhone(phone){return !phone||/^\+?[0-9() .-]{7,20}$/.test(phone)}
function submitRecord(form){if(!form.reportValidity())return;let data=readForm(form),kind=form.dataset.kind,id=form.dataset.id;for(const n of ['fee','capacity'])if(data[n]!==undefined)data[n]=Number(data[n]);if(data.phone&&!validPhone(data.phone)){toast('Enter a valid phone number.','error');return}if(kind==='event'){if(data.start>=data.end){toast('End time must be after start time.','error');return}const conflict=db.events.some(e=>e.id!==id&&e.venueId===data.venueId&&e.date===data.date&&data.start<e.end&&data.end>e.start);if(conflict){toast('This venue already has an event during that time.','error');return}data.image=by('events',id)?.image||['◈','✳','✧','❋'][db.events.length%4]}
if(kind==='session'){if(data.start>=data.end){toast('End time must be after start time.','error');return}let conflict=db.sessions.some(s=>s.id!==id&&s.venueId===data.venueId&&s.date===data.date&&data.start<s.end&&data.end>s.start);if(conflict){toast('This venue already has a session during that time.','error');return}}
if(kind==='participant'&&db.participants.some(p=>p.id!==id&&p.email.toLowerCase()===data.email.toLowerCase())){toast('A participant with this email already exists.','error');return}
let key=kind==='session'?'sessions':kind==='feedback'?'feedback':kind==='organizer'?'organizers':kind==='speaker'?'speakers':kind==='venue'?'venues':kind==='participant'?'participants':'events';if(id){Object.assign(by(key,id),data);toast('Changes saved.')}else{data.id=uid(({events:'EV',venues:'VN',participants:'PT',speakers:'SP',organizers:'OR',sessions:'SS',feedback:'FB'}[key])||'ES');if(kind==='feedback')data.date=day(0);db[key].push(data);toast(`${kind[0].toUpperCase()+kind.slice(1)} added.`)}save();closeModal();render()}
function submitRegistration(form){if(!form.reportValidity())return;let d=readForm(form),event=by('events',d.eventId);if(db.registrations.some(r=>r.eventId===d.eventId&&r.participantId===d.participantId)){toast('This participant is already registered for this event.','error');return}if(db.registrations.filter(r=>r.eventId===d.eventId&&r.status!=='Cancelled').length>=event.capacity){toast('This event has reached its capacity.','error');return}let r={id:uid('REG'),participantId:d.participantId,eventId:d.eventId,date:day(0),payment:d.payment,status:'Approved',attendance:'Not marked'};db.registrations.push(r);db.payments.push({id:uid('PAY'),registrationId:r.id,amount:Number(event.fee),status:d.payment==='Paid'?'Completed':'Pending',date:day(0),method:d.payment==='Paid'?'Simulated card payment':'—'});db.notifications.unshift({id:uid('NT'),title:'Registration confirmed',body:`${personName(r.participantId)} registered for ${event.name}.`,date:day(0),read:false});save();closeModal();render();toast(`Registration ${r.id} confirmed.`)}
function detachEvent(id){db.registrations.filter(r=>r.eventId===id).forEach(r=>db.payments=db.payments.filter(p=>p.registrationId!==r.id));db.registrations=db.registrations.filter(r=>r.eventId!==id);for(const k of ['sessions','speakers','organizers','feedback'])db[k]=db[k].filter(x=>x.eventId!==id)}
function deleteRecord(kind,id){if(!confirm(`Delete this ${kind}? This cannot be undone.`))return;let key=({event:'events',venue:'venues',participant:'participants',speaker:'speakers',organizer:'organizers',session:'sessions',feedback:'feedback',notification:'notifications'})[kind];if(kind==='event')detachEvent(id);if(kind==='venue'){if(db.events.some(e=>e.venueId===id)||db.sessions.some(s=>s.venueId===id)){toast('This venue is assigned to an event or session. Reassign it first.','error');return}}
if(kind==='participant'){let regs=db.registrations.filter(r=>r.participantId===id).map(r=>r.id);db.registrations=db.registrations.filter(r=>r.participantId!==id);db.payments=db.payments.filter(p=>!regs.includes(p.registrationId));db.feedback=db.feedback.filter(f=>f.participantId!==id)}if(kind==='speaker')db.sessions.forEach(s=>{if(s.speakerId===id)s.speakerId=''});db[key]=db[key].filter(x=>x.id!==id);save();render();toast(`${kind} deleted.`)}
function exportCSV(filename,rows){if(!rows.length){toast('There is no data to export.','error');return}const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href);toast('CSV report downloaded.')}
function invoice(id){const p=by('payments',id),r=by('registrations',p?.registrationId);if(!p)return;const html=`<!doctype html><html><head><meta charset="utf-8"><title>Invoice ${p.id}</title><style>body{font:15px Arial;color:#27283b;max-width:700px;margin:60px auto;padding:30px;border:1px solid #ddd}h1{color:#7560e8}table{width:100%;border-collapse:collapse;margin-top:30px}td{padding:12px;border-bottom:1px solid #eee}.total{font-size:22px;font-weight:bold;text-align:right}</style></head><body><h1>EventSphere</h1><h2>Payment receipt</h2><p>Invoice ID: ${p.id}<br>Date: ${dateFmt(p.date)}</p><table><tr><td>Attendee</td><td>${esc(personName(r?.participantId))}</td></tr><tr><td>Event</td><td>${esc(eventName(r?.eventId))}</td></tr><tr><td>Payment method</td><td>${esc(p.method)}</td></tr><tr><td>Status</td><td>${esc(p.status)}</td></tr></table><p class="total">Total: ${money(p.amount)}</p><small>Simulated payment receipt · no real payment was processed.</small><script>window.print()<\/script></body></html>`;let w=window.open('','_blank');if(!w){toast('Allow popups to view the invoice.','error');return}w.document.write(html);w.document.close()}
function generateCertificate(){let e=by('events',$('#certEvent')?.value),p=by('participants',$('#certPerson')?.value);if(!e||!p){toast('Add an event and participant first.','error');return}let cert=uid('CERT');$('#certificateArea').innerHTML=`<div class="certificate-preview"><div style="font-size:35px;color:#b5a364">✳</div><div style="letter-spacing:3px;color:#999;font-size:10px">EVENTSPHERE PRESENTS</div><h2>CERTIFICATE<br>OF PARTICIPATION</h2><p>This certificate is proudly presented to</p><div class="cert-name">${esc(p.name)}</div><p>for participating in <b>${esc(e.name)}</b></p><p>${dateFmt(e.date)}</p><div style="display:flex;justify-content:space-between;margin-top:45px;font-size:10px"><span>____________________<br>Organizer signature</span><span>Certificate ID<br>${cert}</span></div><div style="margin-top:18px">${button('↓ &nbsp; Download certificate','download-cert',true)}</div></div>`;window.currentCert={e,p,cert};toast('Certificate generated.')}
function downloadCertificate(){let c=window.currentCert;if(!c)return;const html=`<!doctype html><html><head><meta charset="utf-8"><title>Certificate ${c.cert}</title><style>@page{size:landscape;margin:0}body{margin:0;font-family:Georgia,serif;background:#fffdf4}.certificate{margin:5%;height:80vh;border:10px double #baa765;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#39364b}.mark{color:#b6a35e;font-size:42px}h1{font:700 36px Arial;color:#7560e8;letter-spacing:6px;margin:24px}h2{font:italic 34px Georgia;border-bottom:1px solid #aaa;padding:0 35px 10px}.meta{display:flex;justify-content:space-between;width:75%;margin-top:45px;font:14px Arial}</style></head><body><div class="certificate"><div class="mark">✳</div><div style="letter-spacing:5px;font:12px Arial">EVENTSPHERE PRESENTS</div><h1>CERTIFICATE OF PARTICIPATION</h1><p>This certificate is proudly presented to</p><h2>${esc(c.p.name)}</h2><p>for participating in <b>${esc(c.e.name)}</b> · ${dateFmt(c.e.date)}</p><div class="meta"><span>____________________<br>Organizer signature</span><span>${c.cert}<br>Certificate ID</span></div></div><script>window.print()<\/script></body></html>`;let w=window.open('','_blank');if(!w){toast('Allow popups to download your certificate.','error');return}w.document.write(html);w.document.close()}
function attachFilters(){if(active==='events'){const update=()=>{let q=$('#eventSearch').value.toLowerCase(),c=$('#eventCat').value,s=$('#eventStatus').value;$('#eventCards').innerHTML=eventCards(db.events.filter(e=>(!q||(e.name+' '+e.description).toLowerCase().includes(q))&&(!c||e.category===c)&&(!s||e.status===s)))};['eventSearch','eventCat','eventStatus'].forEach(id=>$('#'+id).addEventListener('input',update))}if(configs[active]){let update=()=>{let q=$('#tableSearch').value.toLowerCase(),f=$('#tableFilter').value,key=active,all=db[key],event=$('#registrationEventFilter')?.value;let filtered=all.filter(x=>{let val=Object.values(x).join(' ').toLowerCase();return(!q||val.includes(q))&&(!f||(x.status||x.availability||x.payment)===f)&&(!event||x.eventId===event)});$('#tableContainer').innerHTML=tableFor(key,filtered)};$('#tableSearch').addEventListener('input',update);$('#tableFilter').addEventListener('change',update);$('#registrationEventFilter')?.addEventListener('change',update)}if(active==='attendance'){let update=()=>{let q=$('#tableSearch').value.toLowerCase(),e=$('#eventFilter').value;$('#tableContainer').innerHTML=attendanceTable(db.registrations.filter(r=>(!q||personName(r.participantId).toLowerCase().includes(q))&&(!e||r.eventId===e)))};$('#tableSearch').addEventListener('input',update);$('#eventFilter').addEventListener('change',update)}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;switch(a){case'close-modal':closeModal();break;case'new-event':eventForm();break;case'edit-event':eventForm(by('events',id));break;case'view-event':{let x=by('events',id);openModal(x.name,`<div class="modal-form"><p>${esc(x.description)}</p><div class="form-grid"><div><b>Date</b><p>${dateFmt(x.date)} · ${x.start}–${x.end}</p></div><div><b>Venue</b><p>${esc(venueName(x.venueId))}</p></div><div><b>Category</b><p>${esc(x.category)}</p></div><div><b>Fee / capacity</b><p>${money(x.fee)} · ${x.capacity} people</p></div></div><div class="modal-actions"><button class="btn" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="new-registration">＋ Register attendee</button></div></div>`);break}case'delete-event':deleteRecord('event',id);break;case'new-venue':case'new-participant':case'new-speaker':case'new-organizer':{let k=a.slice(4);simpleForm(k);break}case'edit-venue':case'edit-participant':case'edit-speaker':case'edit-organizer':{let k=a.slice(5);simpleForm(k,by(({venue:'venues',participant:'participants',speaker:'speakers',organizer:'organizers'})[k],id));break}case'delete-venue':case'delete-participant':case'delete-speaker':case'delete-organizer':{let k=a.slice(7);deleteRecord(k,id);break}case'new-registration':simpleForm('registration');break;case'approve-reg':{let r=by('registrations',id);r.status='Approved';r.payment='Paid';let p=db.payments.find(p=>p.registrationId===id);if(p)p.status='Completed';save();render();toast('Registration approved and payment marked complete.');break}case'cancel-reg':{if(confirm('Cancel this registration?')){let r=by('registrations',id);r.status='Cancelled';r.payment='Cancelled';db.payments.filter(p=>p.registrationId===id).forEach(p=>p.status='Failed');save();render();toast('Registration cancelled.')}break}case'invoice':invoice(id);break;case'new-session':simpleForm('session');break;case'edit-session':simpleForm('session',by('sessions',id));break;case'delete-session':deleteRecord('session',id);break;case'new-feedback':simpleForm('feedback');break;case'delete-feedback':deleteRecord('feedback',id);break;case'attendance':{let r=by('registrations',id);r.attendance=b.dataset.value;save();render();toast(`Attendance marked ${b.dataset.value.toLowerCase()}.`);break}case'certificate-form':navTo('certificates');break;case'generate-cert':generateCertificate();break;case'download-cert':downloadCertificate();break;case'new-payment':simpleForm('payment');break;case'new-registration':simpleForm('registration');break;case'export-payments':exportCSV('eventsphere-payments.csv',[['Transaction','Registration','Participant','Event','Date','Amount','Status'],...db.payments.map(p=>{let r=by('registrations',p.registrationId);return[p.id,p.registrationId,personName(r?.participantId),eventName(r?.eventId),p.date,p.amount,p.status]})]);break;case'export-registrations':exportCSV('eventsphere-registrations.csv',[['Registration','Participant','Email','Event','Date','Payment','Status','Attendance'],...db.registrations.map(r=>[r.id,personName(r.participantId),by('participants',r.participantId)?.email,eventName(r.eventId),r.date,r.payment,r.status,r.attendance])]);break;case'export-attendance':exportCSV('eventsphere-attendance.csv',[['Participant','Event','Date','Attendance'],...db.registrations.map(r=>[personName(r.participantId),eventName(r.eventId),r.date,r.attendance])]);break;case'go-events':navTo('events');break;case'go-schedule':navTo('schedule');break;case'read-notifications':db.notifications.forEach(n=>n.read=true);save();render();toast('Notifications marked as read.');break;case'delete-notification':deleteRecord('notification',id);break;case'reset-data':if(confirm('Reset all workspace data to the original sample records?')){db=JSON.parse(JSON.stringify(seed));save();render();toast('Sample workspace restored.')}break;case'save-settings':toast('Workspace preferences saved for this session.');break;case'sort-events':db.events.sort((a,b)=>a.date.localeCompare(b.date));render();toast('Events sorted by date.');break;case'certificate-form':generateCertificate();break;default:break}});
document.addEventListener('submit',e=>{if(e.target.id==='recordForm'){e.preventDefault();submitRecord(e.target)}else if(e.target.id==='registrationForm'){e.preventDefault();submitRegistration(e.target)}else if(e.target.id==='paymentForm'){e.preventDefault();let d=readForm(e.target),r=by('registrations',d.registrationId);d.amount=Number(d.amount);db.payments.push({id:uid('PAY'),registrationId:d.registrationId,amount:d.amount,status:d.status,date:day(0),method:d.status==='Completed'?'Simulated payment':'—'});if(r){r.payment=d.status==='Completed'?'Paid':d.status==='Failed'?'Failed':'Pending'}save();closeModal();render();toast('Simulated payment recorded.')}});
document.addEventListener('change',e=>{if(e.target.matches('[name=eventId]')&&$('#regFee'))$('#regFee').value=money(by('events',e.target.value)?.fee||0)});
$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').click()}});
})();

